    pub fn from_env() -> WarpResult<Self> {
        let raw = std::env::var("WARP_SOLANA_RELAY_KEY").map_err(|_| WarpError::AdapterError {
            chain: "solana".into(),
            reason: "WARP_SOLANA_RELAY_KEY not set".into(),
        })?;
        Self::from_base58(&raw)
    }

